func (r *MCPOAuthAuthorizationService) New(ctx context.Context, params MCPOAuthAuthorizationNewParams, opts ...option.RequestOption) (res *CreateMCPOAuthAuthorizationResponse, err error) {
	opts = slices.Concat(r.Options, []option.RequestOption{autoIdempotencyKey()}, opts)
	err = execute(ctx, http.MethodPost, "v1/mcp_oauth_authorizations", params, &res, opts...)
	return
}

// Get sends GET /v1/mcp_oauth_authorizations/{authorization_id}: Get an MCP OAuth authorization.
func (r *MCPOAuthAuthorizationService) Get(ctx context.Context, authorizationID string, opts ...option.RequestOption) (res *MCPOAuthAuthorization, err error) {
	if authorizationID == "" {
		err = errors.New("missing required authorization_id parameter")
		return
	}
	opts = slices.Concat(r.Options, opts)
	err = execute(ctx, http.MethodGet, fmt.Sprintf("v1/mcp_oauth_authorizations/%s", url.PathEscape(authorizationID)), nil, &res, opts...)
	return
}

// Complete sends POST /v1/mcp_oauth/callback: Complete an MCP OAuth authorization. The authorization server's redirect parameters, relayed by the page the user returned to.
func (r *MCPOAuthAuthorizationService) Complete(ctx context.Context, params MCPOAuthAuthorizationCompleteParams, opts ...option.RequestOption) (res *MCPOAuthAuthorization, err error) {
	opts = slices.Concat(r.Options, opts)
	err = execute(ctx, http.MethodPost, "v1/mcp_oauth/callback", params, &res, opts...)
	return
}

